use super::*;
use semio_framework_job::{OperationId,Generation,StepBudget,StepContextOwner,root_cancel_token};
fn policy(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn projected(snapshot:&FlowHostSnapshot,infos:&HistoryFoldIndex<String,OperatorInfo>)->(Tree,HistoryFoldIndex<String,Dictionary>){
 let mut source=FlowEvaluationSource::new();let mut tree=None;
 for _ in 0..100000{let d=source.next_demands(snapshot,infos,512).unwrap();if let Some(value)=source.step(snapshot,infos,policy(d)).unwrap(){tree=Some(value);break}}
 source.begin_close();for _ in 0..100000{if source.terminal_is_empty(){break}let d=source.next_close_demands(512).unwrap();source.close_step(policy(d)).unwrap();}assert!(source.terminal_is_empty());drop(source);let tree=tree.unwrap();
 let mut source=FlowEvaluationSeeds::new();let mut seeds=None;
 for _ in 0..100000{let d=source.next_demands(&tree,512).unwrap();if let Some(value)=source.step(&tree,policy(d)).unwrap(){seeds=Some(value);break}}
 source.begin_close();for _ in 0..100000{if source.terminal_is_empty(){break}let d=source.next_close_demands(512).unwrap();source.close_step(policy(d)).unwrap();}assert!(source.terminal_is_empty());drop(source);(tree,seeds.unwrap())
}
fn preview_request_wire(output:&FlowCurrentOutput<'_>,law:&serde_json::Value,context:&mut StepContextOwner,sequence:&mut u64){
 let row=&law["tessellationWire"];let source=FlowPreviewTessellationRequest::new(output,row["windowId"].as_str().unwrap(),row["windowKindId"].as_str().unwrap(),row["tolerance"].as_f64().unwrap(),row["nodeHash"].as_u64().unwrap()).unwrap();let pointer=output.preview_handle().unwrap().as_ptr();let cancel=root_cancel_token();let mut writer=FlowPreviewTessellationWriter::new();let(mut born,mut freed)=(0,0);let mut wire=None;
 for _ in 0..100000{
  let d=writer.next_demands(&source).unwrap();let grant=policy(d);
  for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(d.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..grant}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..grant}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..grant}),(d.depth>0).then(||RetainedCloneGrant{maximum_depth:d.depth-1,..grant})].into_iter().flatten(){let mut physical=Default::default();let mut cx=context.context(StepBudget::new(1,u64::MAX,denied),cancel.clone(),||Some(1),sequence,&mut physical).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||writer.step(&source,&mut cx));assert!(result.unwrap().is_none());assert_eq!(cx.retained_progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  let mut physical=Default::default();let mut cx=context.context(StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),sequence,&mut physical).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||writer.step(&source,&mut cx));let p=cx.retained_progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!(output.preview_handle().unwrap().as_ptr(),pointer);if let Some(value)=result.unwrap(){wire=Some(value);break;}
 }
 let wire=wire.expect("original funded tessellation writer must complete");let actual:serde_json::Value=serde_json::from_str(&wire).unwrap();assert_eq!(actual,serde_json::json!({"handle":output.preview_handle().unwrap(),"tolerance":row["tolerance"],"nodeHash":row["nodeHash"],"windowId":row["windowId"],"windowKindId":row["windowKindId"]}));assert_eq!(actual.as_object().unwrap().len(),row["keys"].as_array().unwrap().len());for field in ["retained","budget","wallMicros","deadlineUs","operation","generation"]{assert!(actual.get(field).is_none());}
 writer.begin_close();for _ in 0..100000{if writer.terminal_is_empty(){break}let grant=policy(writer.next_close_demands(512).unwrap());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||writer.close_step(grant));let p=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(writer.terminal_is_empty());assert_eq!(born,freed+wire.capacity());assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(writer)).1.released_bytes,0);wire.retire_cold();println!("[DEBUG] Original preview tessellation wire matches independent Serde, escaped UTF8 window, no wire authority, source pointer preserved, denied currencies, exact physical receipt/full close");
}
fn preview_source_transfer(mut read:FlowSourceRead,snapshot:&FlowHostSnapshot,session:&FlowEvalSession,request:&FlowSourceReadRequest<'_>,law:&serde_json::Value,context:&mut StepContextOwner,sequence:&mut u64)->(usize,usize){
 let row=&law["previewSourceTransfer"];let pointer=read.current_output(request).unwrap().preview_handle().unwrap().as_ptr();let binding=read.binding;let d=read.next_preview_source_demands(snapshot,512).unwrap();let grant=policy(d);let cancel=root_cancel_token();
 for field in row["denials"].as_array().unwrap(){let denied=match field.as_str().unwrap(){"items"=>RetainedCloneGrant{maximum_items:0,..grant},"copy"=>RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..grant},"depth"=>RetainedCloneGrant{maximum_depth:d.depth-1,..grant},_=>unreachable!()};let mut physical=Default::default();let mut cx=context.context(StepBudget::new(1,u64::MAX,denied),cancel.clone(),||Some(1),sequence,&mut physical).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||read.into_preview_source(snapshot,[1;32],session,request,&mut cx));let(outcome,original)=result.err().expect("denied donation must return original source");assert!(matches!(outcome,FlowPreviewSourceTransfer::Working));assert_eq!(cx.retained_progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));read=original;assert_eq!(read.binding,binding);assert_eq!(read.current_output(request).unwrap().preview_handle().unwrap().as_ptr(),pointer);}
 let mut physical=Default::default();let mut cx=context.context(StepBudget::new(1,u64::MAX,grant),cancel.clone(),||Some(1),sequence,&mut physical).unwrap();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||read.into_preview_source(snapshot,[1;32],session,request,&mut cx));let source=result.unwrap_or_else(|_|panic!("funded original source donation must complete"));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress().copied_items,1);assert_eq!(cx.retained_progress().copied_bytes,d.copy_bytes);drop(cx);assert_eq!(source.original_handle().as_ptr(),pointer);assert_eq!(source.original_revision(),[1;32]);assert_eq!(source.original_operation(),(row["operation"].as_u64().unwrap(),row["generation"].as_u64().unwrap()));let wire=&law["tessellationWire"];let request=FlowPreviewTessellationRequest::from_source(&source,wire["windowId"].as_str().unwrap(),wire["windowKindId"].as_str().unwrap(),wire["tolerance"].as_f64().unwrap(),wire["nodeHash"].as_u64().unwrap()).unwrap();assert!(matches!(semio_framework_pack_json::JsonWriteSource::node_at_path(&request,&[0]).unwrap(),semio_framework_pack_json::JsonWriteNode::String(handle)if handle.as_ptr()==pointer));drop(request);
 let mut owner=ControlledRetirement::new(source).unwrap_or_else(|_|unreachable!());let(mut born,mut freed)=(0,0);for _ in 0..250000{if owner.terminal_is_empty(){break}let d=owner.selected_demand(512).unwrap();let grant=policy(d);for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..grant}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..grant})].into_iter().flatten(){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(denied));assert_eq!(result.unwrap().progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(grant));let p=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;}assert!(owner.terminal_is_empty());assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner)).1.released_bytes,0);println!("[DEBUG] Donated preview source keeps original handle memory and operation/generation/revision, denies whole source without effects, source-specific wire borrows retained identity, full funded close Drop0");(born,freed)
}
fn retire_fixture_host(host:FlowHost){
 let mut original=FlowHostRetirement::new(host);
 while !original.terminal_is_empty(){
  let copy=original.next_close_copy_byte_demand().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:original.next_close_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:original.next_close_release_byte_demand().unwrap(),maximum_depth:original.next_close_depth_demand().unwrap()};
  let step=original.close_step(grant).unwrap();
  if step.progress()==Default::default(){if let Some(store)=original.state.source.as_ref().and_then(|host|host.history_store.as_ref()){eprintln!("[DEBUG] Original query fixture store phase={} displaced={} hostPhase={:?} grant={grant:?} receipt={:?}",store.close_owned_phase_witness(),store.close_displaced_witness(),original.close_phase(),step.progress());}}
  assert_ne!(step.progress().copied_items,0,"original query fixture Host close stalled without changing its exact grant");
 }
}
fn install(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().find(|root|root.join("bun.lock").is_file()).unwrap();let descriptor:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(root.join("✏️s/🔌️plugins/🌊️flow/🧩️extensions/📐️brep/🧩️component/🔣️.json")).unwrap()).unwrap();install_flow_extension_manifest("brep",descriptor["manifest"]["topicContributions"][0]["payload"]["manifestJson"].as_str().unwrap()).unwrap();}

